// === Tab: mySketch ===
let shaderProg;
let timeStart;

// ===== GLSL SHADER =====
const vert = `
precision mediump float;
attribute vec3 aPosition;
varying vec2 vTexCoord;
void main() {
  vTexCoord = (aPosition.xy + 1.0) * 0.5;
  gl_Position = vec4(aPosition, 1.0);
}
`;

const frag = `
precision mediump float;

uniform float u_time;
uniform bool u_noiseOn;
uniform float u_noiseIntensity;
uniform float u_zoom;

uniform float u_glitchAmount;
uniform float u_scanlineStrength;
uniform float u_pixelSizeBase;
uniform float u_rippleStrength;
uniform float u_glowStrength;
uniform float u_flickerStrength;

uniform int u_patternShape;
uniform bool u_showGrid;

// Pattern params (старые)
uniform float u_ringsFreq;
uniform float u_ringsIntensity;
uniform float u_squareDensity;
uniform float u_squareSmoothness;
uniform float u_stripesFreq;
uniform float u_stripesWidth;
uniform int   u_stripesOrientation;
uniform int   u_radialLinesCount;
uniform float u_radialLinesWidth;
uniform float u_checkerDensity;

// ===== NEW SUBPATTERN MODE UNIFORMS =====
uniform int   u_subPatternMode;    // 0=Concentric, 1=Ripples, 2=Stripes, 3=LogSpiral, 4=Voronoi, 5=PolarCheck
uniform float u_waveFreq, u_waveSpeed, u_waveAmp;
uniform float u_stripeCount, u_stripeSpeed, u_stripeWidth;
uniform float u_spiralDensity, u_spiralTurns, u_spiralWidth;
uniform int   u_pointCount;
uniform float u_cellSize;
uniform float u_polarCheckerDensity;
uniform vec3  u_keyColor;

varying vec2 vTexCoord;

// Simple noise
float noise(vec2 p){
  return fract(cos(dot(p, vec2(12.9898,78.233))) * 43758.5453123);
}

float fbm(vec2 p){
  float f = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for(int i=0; i<4; i++){
    f += amp * noise(p * freq);
    freq *= 2.0;
    amp *= 0.5;
  }
  return f;
}

// Patterns
float circlePattern(vec2 uv, float freq){
  float r = length(uv);
  float val = smoothstep(0.5/freq, 0.0, abs(fract(r*freq)-0.5));
  return val;
}
float squarePattern(vec2 uv, float density, float smooth){
  vec2 grid = fract(uv * density);
  vec2 dist = min(grid, 1.0 - grid);
  float edge = min(dist.x, dist.y);
  return smoothstep(smooth, 0.0, edge);
}
float stripesPattern(vec2 uv, float freq, float width, int orientation){
  float coord = 0.0;
  if(orientation == 0) coord = uv.y;
  else if(orientation == 1) coord = uv.x;
  else coord = uv.x + uv.y;
  float f = fract(coord * freq);
  return step(f, width);
}
float radialLinesPattern(vec2 uv, int count, float width){
  float angle = atan(uv.y, uv.x);
  float sector = fract(angle / (6.2831853 / float(count)));
  return step(sector, width);
}
float checkerboardPattern(vec2 uv, float density){
  vec2 c = floor(uv * density);
  float v = mod(c.x + c.y, 2.0);
  return v;
}

void main() {
  vec2 uv = vTexCoord - 0.5;
  uv *= u_zoom;

  float r = length(uv);
  float a = atan(uv.y, uv.x);

  float patternVal = 0.0;

  // ======= SUBPATTERN MODES =======
  if(u_subPatternMode == 0){
    // Con Rings
    patternVal = circlePattern(uv, u_ringsFreq) * u_ringsIntensity;
  } else if(u_subPatternMode == 1){
    // Rainbow Rings
    float w = sin(r * u_waveFreq - u_time * u_waveSpeed) * u_waveAmp;
    patternVal = smoothstep(0.0, 0.02, abs(w));
  } else if(u_subPatternMode == 2){
    // Rays
    float s = fract((a/6.2831853)*u_stripeCount + u_time*u_stripeSpeed);
    patternVal = step(u_stripeWidth, s);
  } else if(u_subPatternMode == 3){
    // Log Spiral
    float sp = fract(log(r+1e-4)*u_spiralDensity - (a/6.2831853)*u_spiralTurns);
    patternVal = 1.0 - smoothstep(0.0, u_spiralWidth, abs(sp-0.5));
  } else if(u_subPatternMode == 4){
    // Voronoi
    float cell = sin(r * float(u_pointCount) * 2.0 + u_time) + noise(uv * 12. + u_time * 0.2);
    patternVal = smoothstep(u_cellSize, 0.0, abs(cell));
  } else if(u_subPatternMode == 5){
    // Checherboard
    float cr=floor(r*u_polarCheckerDensity), ca=floor((a/6.2831853)*u_polarCheckerDensity);
    patternVal = mod(cr+ca,2.0);
  }

  // ====== Graphics ======
  float waveDisplacementX = sin(uv.y * 10.0 + u_time * 3.0) * 0.02;
  float waveDisplacementY = cos(uv.x * 10.0 + u_time * 3.0) * 0.02;
  uv.x += waveDisplacementX * patternVal;
  // uv.y += waveDisplacementY * patternVal;
	uv.y += tan(waveDisplacementY) * patternVal;

  float scanlines = sin(uv.y * 4.0) * u_scanlineStrength;

  float ca_offset = 0.005 * cos(u_time);
  vec3 chromatic = vec3(
    sin(r * 10.0 - u_time * 3.0 + ca_offset),
    sin(r * 10.0 - u_time * 3.0),
    sin(r * 10.0 - u_time * 3.0 - ca_offset)
  ) * 0.5 + 0.5;

  vec3 neonColor = u_keyColor;

  // Main Color and Chromatic
  vec3 baseColor = mix(neonColor, chromatic, patternVal);
  vec3 finalColor = baseColor + scanlines;

  float glitch = step(0.99, fract(sin(uv.y * 100.0 + u_time * 5.0) * 43758.5453123));
  uv.x += glitch * u_glitchAmount;

  vec3 glow = vec3(1.0, 0.5, 0.8) * smoothstep(0.3, 0.1, r);
  finalColor += glow * u_glowStrength;

  float pixelSize = u_pixelSizeBase + 0.005 * (1.0 / tan(u_time * 2.0 + 0.1));
  uv = floor(uv / pixelSize) * pixelSize;

  float ripple = sin(r * 15.0 - u_time * 5.0) * 0.2;
  uv.x += ripple * u_rippleStrength;
  uv.y += ripple * u_rippleStrength;

  if(u_showGrid){
    float grid = mod(uv.x * 200.0, 1.0) > 0.9 || mod(uv.y * 20.0, 1.0) > 0.9 ? 0.3 : 0.0;
    finalColor += vec3(grid);
  }

  float flicker = sin(u_time * 10.0) * u_flickerStrength;
  finalColor *= 1.0 + flicker;

  finalColor = mix(finalColor, vec3(0.0), smoothstep(0.7, 1.2, r));
  float starfield = step(0.995, fract(sin(dot(uv, vec2(12.9898, 78.233)) * 43758.5453 + u_time)));
  finalColor -= vec3(starfield * 0.8);
  float plasma = cos(uv.x * 10.0 + u_time) * sin(uv.y * 10.0 + u_time) * 0.5 + 0.5;
  finalColor = mix(finalColor, vec3(1.0, 0.2, 0.3), plasma * 0.3);
  float motionBlur = smoothstep(0.0, 1.0, abs(1.0 / tan(u_time * 0.5 + 0.1)));
  finalColor = mix(finalColor, vec3(0.0), motionBlur * 0.2);
  float noiseVal = u_noiseOn ? fbm(uv * 10.0 + u_time * 0.1) : 0.0;
  finalColor += vec3(noiseVal * u_noiseIntensity);

  float waterRipple = tan(r * 12.0 - u_time * 6.0) * 0.05;
  uv.x += waterRipple;
  uv.y += waterRipple;

  float electricPulse = tan(u_time * 8.0 + uv.x * 15.0) * 0.3;
  finalColor -= vec3(electricPulse, electricPulse * 0.5, electricPulse * 0.2);

  float vignette = smoothstep(1.2, 0.5, r);
  gl_FragColor = vec4(finalColor * vignette, 1.0);
}
`;

// ===== P5.js MAIN CODE =====

let gui;
let paused = false;
let pausedTime = 0;

let params = {
  // OLD Pattern Controls
  patternShape: 0,
  ringsFreq: 10.0, ringsIntensity: 1.0,
  squareDensity: 10.0, squareSmoothness: 0.02,
  stripesFreq: 20.0, stripesWidth: 0.3, stripesOrientation: 0,
  radialLinesCount: 6, radialLinesWidth: 0.15,
  checkerDensity: 20.0,
  // NEW Subpattern Controls
  subPatternMode: 0,
  waveFreq: 12.0, waveSpeed: 1.2, waveAmp: 0.7,
  stripeCount: 12.0, stripeSpeed: 1.0, stripeWidth: 0.07,
  spiralDensity: 8.0, spiralTurns: 4.0, spiralWidth: 0.12,
  pointCount: 10, cellSize: 0.08,
  polarCheckerDensity: 10.0,
  keyColor: [160, 255, 200], // RGB, 0..255
  // Effects & Canvas
  noiseOn: true, noiseIntensity: 0.1,
  zoom: 0.15, glitchAmount: 0.02, scanlineStrength: 0.1,
  pixelSizeBase: 0.01, rippleStrength: 0.1,
  glowStrength: 0.25, flickerStrength: 0.05, animationSpeed: 1.0,
  formFactor: 'Square',
  exportWidth: 800, exportHeight: 800, exportPixelDensity: 2,
  showGrid: true,
  togglePause: function () {
    paused = !paused;
    if (paused) { pausedTime = millis(); }
    else { timeStart += millis() - pausedTime; }
  },
  saveImage: function () {
    let oldW = width, oldH = height, oldPD = pixelDensity();
    resizeCanvas(params.exportWidth, params.exportHeight);
    pixelDensity(params.exportPixelDensity);
    redraw();
    saveCanvas('background_' + nf(year(),4) + nf(month(),2) + nf(day(),2),'png');
    resizeCanvas(oldW, oldH);
    pixelDensity(oldPD);
  }
};

function setup() {
  if (params.formFactor === 'Square') createCanvas(800, 800, WEBGL);
  else createCanvas(1280, 720, WEBGL);
  noStroke();
  shaderProg = createShader(vert, frag);
  gui = new dat.GUI();

  // OLD patterns
  let patternFolder = gui.addFolder('Pattern Controls');
  patternFolder.add(params, 'patternShape', {Circle:0, Square:1, Stripes:2, RadialLines:3, Checkerboard:4}).name('Pattern Shape');
  patternFolder.add(params, 'ringsFreq', 1, 30).step(0.1).name('Rings Freq');
  patternFolder.add(params, 'ringsIntensity', 0, 2).step(0.01).name('Rings Intensity');
  patternFolder.add(params, 'squareDensity', 1, 50).step(1).name('Square Density');
  patternFolder.add(params, 'squareSmoothness', 0.001, 0.1).step(0.001).name('Square Smoothness');
  patternFolder.add(params, 'stripesFreq', 1, 50).step(1).name('Stripes Freq');
  patternFolder.add(params, 'stripesWidth', 0.01, 1).step(0.01).name('Stripes Width');
  patternFolder.add(params, 'stripesOrientation', {Horizontal:0, Vertical:1, Diagonal:2}).name('Stripes Orient');
  patternFolder.add(params, 'radialLinesCount', 1, 30).step(1).name('Radial Lines');
  patternFolder.add(params, 'radialLinesWidth', 0.01, 1).step(0.01).name('Radial Width');
  patternFolder.add(params, 'checkerDensity', 1, 50).step(1).name('Checker Density');
  patternFolder.open();

  // ===== NEW SUBPATTERN CONTROLS =====
  gui.add(params, 'subPatternMode', {Concentric:0, Ripples:1, Stripes:2, LogSpiral:3, Voronoi:4, PolarCheck:5}).name('Subpattern Mode');
  let sp = gui.addFolder('Subpattern');
  sp.add(params, 'waveFreq', 1, 50).name('Wave Freq');
  sp.add(params, 'waveSpeed', 0, 5).name('Wave Speed');
  sp.add(params, 'waveAmp', 0, 1).name('Wave Amp');
  sp.add(params, 'stripeCount', 1, 64).name('Stripe Count');
  sp.add(params, 'stripeSpeed', 0, 5).name('Stripe Speed');
  sp.add(params, 'stripeWidth', 0.005, 0.2).name('Stripe Width');
  sp.add(params, 'spiralDensity', 1, 50).name('Spiral Density');
  sp.add(params, 'spiralTurns', 1, 10).name('Spiral Turns');
  sp.add(params, 'spiralWidth', 0.01, 0.5).name('Spiral Width');
  sp.add(params, 'pointCount', 1, 64).step(1).name('Voronoi Points');
  sp.add(params, 'cellSize', 0.01, 0.5).name('Cell Size');
  sp.add(params, 'polarCheckerDensity', 1, 50).name('Polar Checker Density');
  sp.addColor(params, 'keyColor').name('Key Color');
  sp.open();

  // Effects & Canvas Controls
  let effectFolder = gui.addFolder('Effects & Canvas Controls');
  effectFolder.add(params, 'noiseOn').name('Noise On');
  effectFolder.add(params, 'noiseIntensity', 0, 1).step(0.01).name('Noise Intensity');
  effectFolder.add(params, 'zoom', 0.01, 1).step(0.01).name('Scale (Zoom)');
  effectFolder.add(params, 'glitchAmount', 0, 0.1).step(0.001).name('Glitch Amount');
  effectFolder.add(params, 'scanlineStrength', 0, 0.3).step(0.005).name('Scanline Strength');
  effectFolder.add(params, 'pixelSizeBase', 0.001, 0.05).step(0.001).name('Pixel Size Base');
  effectFolder.add(params, 'rippleStrength', 0, 0.3).step(0.005).name('Ripple Strength');
  effectFolder.add(params, 'glowStrength', 0, 1).step(0.01).name('Glow Strength');
  effectFolder.add(params, 'flickerStrength', 0, 0.1).step(0.001).name('Flicker Strength');
  effectFolder.add(params, 'animationSpeed', 0, 3).step(0.01).name('Animation Speed');
  effectFolder.add(params, 'formFactor', ['Square', 'Horizontal']).name('Form Factor').onChange(() => {
    if (params.formFactor === 'Square') {
      resizeCanvas(800, 800);
      params.exportWidth = 800;
      params.exportHeight = 800;
    } else {
      resizeCanvas(1280, 720);
      params.exportWidth = 1280;
      params.exportHeight = 720;
    }
  });
  effectFolder.add(params, 'exportWidth', 200, 3840).step(10).name('Export Width (px)');
  effectFolder.add(params, 'exportHeight', 200, 2160).step(10).name('Export Height (px)');
  effectFolder.add(params, 'exportPixelDensity', 1, 4).step(1).name('Export Pixel Density');
  effectFolder.add(params, 'showGrid').name('Show Grid');
  effectFolder.add(params, 'togglePause').name('Pause Animation');
  effectFolder.add(params, 'saveImage').name('Save PNG');
  effectFolder.open();

  timeStart = millis();
  pixelDensity(2);
  frameRate(60);
}

function draw() {
  shader(shaderProg);

  let elapsed = paused ? (pausedTime - timeStart) : (millis() - timeStart);
  let animTime = (elapsed / 1000.0) * params.animationSpeed;

  // ======= PASS UNIFORMS =======
  shaderProg.setUniform('u_time', animTime);
  shaderProg.setUniform('u_noiseOn', params.noiseOn);
  shaderProg.setUniform('u_noiseIntensity', params.noiseIntensity);
  shaderProg.setUniform('u_zoom', params.zoom);
  shaderProg.setUniform('u_glitchAmount', params.glitchAmount);
  shaderProg.setUniform('u_scanlineStrength', params.scanlineStrength);
  shaderProg.setUniform('u_pixelSizeBase', params.pixelSizeBase);
  shaderProg.setUniform('u_rippleStrength', params.rippleStrength);
  shaderProg.setUniform('u_glowStrength', params.glowStrength);
  shaderProg.setUniform('u_flickerStrength', params.flickerStrength);

  shaderProg.setUniform('u_patternShape', params.patternShape);
  shaderProg.setUniform('u_ringsFreq', params.ringsFreq);
  shaderProg.setUniform('u_ringsIntensity', params.ringsIntensity);
  shaderProg.setUniform('u_squareDensity', params.squareDensity);
  shaderProg.setUniform('u_squareSmoothness', params.squareSmoothness);
  shaderProg.setUniform('u_stripesFreq', params.stripesFreq);
  shaderProg.setUniform('u_stripesWidth', params.stripesWidth);
  shaderProg.setUniform('u_stripesOrientation', params.stripesOrientation);
  shaderProg.setUniform('u_radialLinesCount', params.radialLinesCount);
  shaderProg.setUniform('u_radialLinesWidth', params.radialLinesWidth);
  shaderProg.setUniform('u_checkerDensity', params.checkerDensity);

  // NEW SUBPATTERN
  shaderProg.setUniform('u_subPatternMode', params.subPatternMode);
  shaderProg.setUniform('u_waveFreq', params.waveFreq);
  shaderProg.setUniform('u_waveSpeed', params.waveSpeed);
  shaderProg.setUniform('u_waveAmp', params.waveAmp);
  shaderProg.setUniform('u_stripeCount', params.stripeCount);
  shaderProg.setUniform('u_stripeSpeed', params.stripeSpeed);
  shaderProg.setUniform('u_stripeWidth', params.stripeWidth);
  shaderProg.setUniform('u_spiralDensity', params.spiralDensity);
  shaderProg.setUniform('u_spiralTurns', params.spiralTurns);
  shaderProg.setUniform('u_spiralWidth', params.spiralWidth);
  shaderProg.setUniform('u_pointCount', params.pointCount);
  shaderProg.setUniform('u_cellSize', params.cellSize);
  shaderProg.setUniform('u_polarCheckerDensity', params.polarCheckerDensity);

  // Convert Color [0..255] to [0..1]
  let col = params.keyColor;
  shaderProg.setUniform('u_keyColor', [col[0]/255, col[1]/255, col[2]/255]);

  shaderProg.setUniform('u_showGrid', params.showGrid);

  beginShape();
  vertex(-1, -1, 0);
  vertex(1, -1, 0);
  vertex(1, 1, 0);
  vertex(-1, 1, 0);
  endShape(CLOSE);
}

function keyPressed() {
  if (key === 's' || key === 'S') params.saveImage();
  if (key === 'p' || key === 'P') params.togglePause();
}

